(function(root){
 'use strict';
 const schemas={
  participants:'study_id participant_id task_id condition_code price_factor position_factor label_factor markup_percent layout_mode placement_rule budget_pkr assigned_at started_at saved_at completed_at status language age_at_registration gender university height_cm weight_kg waist_cm anthropometry_entered_at questionnaire_code questionnaire_link_status consent_version consented_at quantity amount_pkr energy_kcal upf_energy_kcal unknown_energy_kcal upf_energy_share protocol_version catalog_version rules_version layout_version synthetic',
  purchases:'study_id participant_id task_id condition_code price_factor position_factor label_factor product_id quantity base_price_pkr unit_price_pkr line_total_pkr size unit sale_unit pieces_per_unit nova energy_kcal fat_g sugars_g salt_g catalog_version completed_at',
  events:'study_id participant_id task_id condition_code id event_type client_time received_at details',
  catalog:'study_id catalog_version protocol_version rules_version layout_version id zh en ur size unit price kcal fat sugar salt nova eligible catalogOrder popularityRank synthetic classificationStatus displayZone saleUnit portionCount aliases'
 };
 const notes={sale_unit:'Buying unit; piece is one individually purchased toffee',pieces_per_unit:'Number of pieces in one buying unit, where applicable',displayZone:'Fixed shelf / fridge / snack counter / freezer area; placement changes within area',saleUnit:'Buying unit; do not confuse grams with number of units',portionCount:'Pieces or portions in one buying unit',aliases:'Alternative local and search names',study_id:'Study identifier',participant_id:'Pseudonymous participant ID; not an auth account ID',task_id:'One task per participant per study',condition_code:'Three bits P O L; e.g. 101 = markup, control layout, labels',price_factor:'0 original price; 1 NOVA4-only markup',position_factor:'0 frozen control layout; 1 alternatives-eye',label_factor:'0 no nutrient/UPF information; 1 combined nutrient and UPF label package',markup_percent:'Candidate markup used when price_factor=1; percent',upf_energy_share:'0-1; null if zero total energy or any unclassified-NOVA energy',status:'in_progress means no completed outcome; completed empty basket is a valid zero purchase',energy_kcal:'Purchased energy in kcal; null for uncompleted tasks',upf_energy_kcal:'Purchased NOVA4 energy in kcal; null for uncompleted tasks',unknown_energy_kcal:'Purchased energy from unknown NOVA foods',amount_pkr:'Total spend in PKR',age_at_registration:'Age in completed years on registration, not age at export',height_cm:'Entered height in cm',weight_kg:'Entered weight in kg',waist_cm:'Entered waist circumference in cm',anthropometry_entered_at:'Server entry time; not physical measurement date',questionnaire_link_status:'pending_review is not a verified questionnaire match',client_time:'Untrusted client clock; not eye tracking or verified exposure',received_at:'Server receipt timestamp in UTC',details:'Sanitized interaction fields; not gaze or attention measures',kcal:'Synthetic per100g or per100ml energy in kcal',fat:'Total fat g per100g or per100ml',sugar:'Total sugars g per100g or per100ml',salt:'Salt g per100g or per100ml',price:'Baseline pack price in PKR',synthetic:'true means illustrative data, not reviewed field measurements',eligible:'Preset comparator candidate, not a universal health grade',nova:'1-4 or null unknown; independent from nutrient-light thresholds',quantity:'Number of packs/portions; zero allowed only in a completed task summary'};
 const columns=dataset=>{if(!schemas[dataset])throw new Error('invalidDataset');return schemas[dataset].split(' ');};
 function cell(value){let s=value===null||value===undefined?'':typeof value==='object'?JSON.stringify(value):String(value);if(/^[\s\uFEFF]*[=+\-@]/.test(s)||/^[\t\r\n]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
 function csv(rows,dataset){const cols=columns(dataset);return '\uFEFF'+[cols.map(cell).join(','),...rows.map(r=>cols.map(k=>cell(r[k])).join(','))].join('\r\n')+'\r\n';}
 function dictionary(){return '\uFEFF'+['dataset,field,description',...Object.keys(schemas).flatMap(d=>columns(d).map(k=>[d,k,notes[k]||(/_at$/.test(k)?'Server timestamp in UTC':k)].map(cell).join(',')))].join('\r\n')+'\r\n';}
 const api={csv,cell,columns,dictionary};root.CampusAdminCore=api;if(typeof module!=='undefined'&&module.exports)module.exports=api;
})(globalThis);
